CREATE TABLE IF NOT EXISTS contingency_plans (id INTEGER PRIMARY KEY AUTOINCREMENT,app_id TEXT NOT NULL DEFAULT 'principal-ed',subject_component TEXT NOT NULL,subject_type TEXT NOT NULL,subject_id TEXT NOT NULL,title TEXT NOT NULL,trigger_description TEXT NOT NULL,trigger_source TEXT,owner_type TEXT NOT NULL DEFAULT 'user',owner_id TEXT NOT NULL,activation_deadline TEXT,activation_notes TEXT,activated_at TEXT,activated_by TEXT,resolution_summary TEXT,resolved_at TEXT,resolved_by TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','active','resolved','withdrawn')),created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')));
CREATE TABLE IF NOT EXISTS contingency_actions (id INTEGER PRIMARY KEY AUTOINCREMENT,plan_id INTEGER NOT NULL,sequence_number INTEGER NOT NULL CHECK(sequence_number>0),action TEXT NOT NULL,owner_type TEXT,owner_id TEXT,due_offset_minutes INTEGER,completion_notes TEXT,completed_at TEXT,completed_by TEXT,status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','in_progress','completed','skipped','withdrawn')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),UNIQUE(plan_id,sequence_number),FOREIGN KEY(plan_id) REFERENCES contingency_plans(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS contingency_resources (id INTEGER PRIMARY KEY AUTOINCREMENT,plan_id INTEGER NOT NULL,resource_component TEXT NOT NULL,resource_type TEXT NOT NULL,resource_id TEXT,description TEXT NOT NULL,quantity INTEGER NOT NULL DEFAULT 1 CHECK(quantity>0),status TEXT NOT NULL DEFAULT 'required' CHECK(status IN ('required','secured','unavailable','withdrawn')),created_at TEXT NOT NULL DEFAULT(datetime('now')),updated_at TEXT NOT NULL DEFAULT(datetime('now')),FOREIGN KEY(plan_id) REFERENCES contingency_plans(id) ON DELETE CASCADE);
CREATE INDEX IF NOT EXISTS idx_contingency_subject ON contingency_plans(app_id,subject_component,subject_type,subject_id,status);CREATE INDEX IF NOT EXISTS idx_contingency_actions ON contingency_actions(plan_id,sequence_number,status);CREATE INDEX IF NOT EXISTS idx_contingency_resources ON contingency_resources(plan_id,status);
